import{_ as e,c as t,o as r,ag as o}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/settings.md","filePath":"zh-TW/guide/settings.md","lastUpdated":1791311600000}'),i={name:"zh-TW/guide/settings.md"};function l(n,a,s,d,h,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h1><p>nPlyr 的設定視窗按標籤頁組織。本頁帶你了解大多數人最先更改的若干項。</p><h2 id="外觀與語言" tabindex="-1">外觀與語言 <a class="header-anchor" href="#外觀與語言" aria-label="Permalink to &quot;外觀與語言&quot;">​</a></h2><h3 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to &quot;主題&quot;">​</a></h3><p>nPlyr 內建多個主題，每個都以一個標誌性的強調色為基調。切換主題時，整個介面——包括每一個開啟的視窗——都會立即更新。你也可以自動<strong>跟隨系統外觀</strong>（淺色 / 深色）。</p><h3 id="語言" tabindex="-1">語言 <a class="header-anchor" href="#語言" aria-label="Permalink to &quot;語言&quot;">​</a></h3><p>介面已在地化為 <strong>25 種語言</strong>。更改語言會在所有已開啟視窗與選單列上立即生效——無需重新啟動。（這一即時切換是透過在語言變化時重建每個視窗的視圖來實現的。）</p><h2 id="一般" tabindex="-1">一般 <a class="header-anchor" href="#一般" aria-label="Permalink to &quot;一般&quot;">​</a></h2><ul><li><strong>瀏覽器 user-agent</strong>——選擇 <em>自動</em>、<em>行動裝置</em>、<em>桌面端（PC）</em>，或貼上一段<strong>自訂</strong> UA。該 UA 由<a href="/zh-TW/guide/browser.html">嗅探器</a>以及播放/解析在需要時採用。規則也可以指定自己的 UA；只有當選擇跟隨規則的值時，齒輪設定才會覆寫它。</li><li><strong>檔案關聯</strong>——讓 nPlyr 當你在 Finder 中雙擊本機影音檔案（<code>.mp4</code>、<code>.mkv</code>、<code>.mov</code>、<code>.m4v</code>、<code>.webm</code>、<code>.flv</code>、<code>.mka</code> 等）時開啟它們。</li></ul><h2 id="下載" tabindex="-1">下載 <a class="header-anchor" href="#下載" aria-label="Permalink to &quot;下載&quot;">​</a></h2><ul><li>已下載媒體的預設儲存位置。</li><li>是否提供<strong>邊下邊播</strong>。</li><li>清晰度預設值，以及是否自動下載字幕。</li></ul><h2 id="播放器" tabindex="-1">播放器 <a class="header-anchor" href="#播放器" aria-label="Permalink to &quot;播放器&quot;">​</a></h2><ul><li>預設播放速度。</li><li>手勢偏好（觸控板 / 觸控靈敏度）。</li><li>畫中畫與 AirPlay 預設值。</li></ul><h2 id="去廣告" tabindex="-1">去廣告 <a class="header-anchor" href="#去廣告" aria-label="Permalink to &quot;去廣告&quot;">​</a></h2><p>訂閱 Chrome 相容的過濾清單。nPlyr 會在瀏覽器中以及播放期間過濾請求。去廣告與邊下邊播互斥。</p><h2 id="小程式" tabindex="-1">小程式 <a class="header-anchor" href="#小程式" aria-label="Permalink to &quot;小程式&quot;">​</a></h2><p>管理已匯入的小程式與規則來源：新增、編輯、重新排列與刪除。<strong>免費層級</strong>會限制小程式的數量；解鎖後移除該限制，以一次性購買形式儲存。請參閱<a href="/zh-TW/guide/miniapps.html">小程式</a>。</p>',17)])])}const g=e(i,[["render",l]]);export{m as __pageData,g as default};
